To build a small local stationery storefront called Paper Harbor, we need to create a simple HTML file with embedded JavaScript. This will include a list of products, a search and category filtering feature, a cart with quantities, remove controls, and a correct total. The cart should also persist across page reloads. We will use synthetic data and keep everything local.

Here's a step-by-step approach:

1. **Create the HTML file**: This will include the structure of the storefront.
2. **Add JavaScript**: This will handle the logic for filtering, adding items to the cart, updating the cart, and persisting the cart across page reloads.

Let's start by creating the HTML file.

### Step 1: Create the HTML file

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Paper Harbor</title>
    <style>
        body {
            font-family: Arial, sans-serif;
        }
        .product {
            border: 1px solid #ccc;
            padding: 10px;
            margin: 10px;
        }
        .cart {
            margin-top: 20px;
        }
        .cart-item {
            border: 1px solid #ccc;
            padding: 10px;
            margin: 10px;
        }
    </style>
</head>
<body>
    <h1>Paper Harbor</h1>
    <input type="text" id="search" placeholder="Search products...">
    <select id="category">
        <option value="all">All</option>
        <option value="paper">Paper</option>
        <option value="stationery">Stationery</option>
    </select>
    <div id="products"></div>
    <div class="cart" id="cart">
        <h2>Cart</h2>
        <div id="cart-items"></div>
        <p>Total: <span id="total">0</span></p>
        <button onclick="checkout()">Checkout</button>
    </div>

    <script>
        const products = [
            { name: "A4 Paper", price: 10, category: "paper" },
            { name: "Pen", price: 2, category: "stationery" },
            { name: "Notebook", price: 5, category: "paper" },
            { name: "Eraser", price: 1, category: "stationery" },
            { name: "Highlighter", price: 3, category: "stationery" },
            { name: "Stapler", price: 4, category: "stationery" }
        ];

        const cart = JSON.parse(localStorage.getItem('cart')) || [];

        function renderProducts() {
            const productsDiv = document.getElementById('products');
            productsDiv.innerHTML = '';
            products.forEach(product => {
                if (product.category === document.getElementById('category').value || document.getElementById('category').value === 'all') {
                    const productDiv = document.createElement('div');
                    productDiv.className = 'product';
                    productDiv.innerHTML = `
                        <h3>${product.name}</h3>
                        <p>Price: $${product.price}</p>
                        <button onclick="addToCart('${product.name}', ${product.price})">Add to Cart</button>
                    `;
                    productsDiv.appendChild(productDiv);
                }
            });
        }

        function addToCart(name, price) {
            const item = cart.find(item => item.name === name);
            if (item) {
                item.quantity++;
            } else {
                cart.push({ name, price, quantity: 1 });
            }
            updateCart();
            localStorage.setItem('cart', JSON.stringify(cart));
        }

        function updateCart() {
            const cartItemsDiv = document.getElementById('cart-items');
            cartItemsDiv.innerHTML = '';
            let total = 0;
            cart.forEach(item => {
                const cartItemDiv = document.createElement('div');
                cartItemDiv.className = 'cart-item';
                cartItemDiv.innerHTML = `
                    <p>${item.name} x ${item.quantity} - $${item.price * item.quantity}</p>
                    <button onclick="removeFromCart('${item.name}')">Remove</button>
                `;
                cartItemsDiv.appendChild(cartItemDiv);
                total += item.price * item.quantity;
            });
            document.getElementById('total').innerText = total;
        }

        function removeFromCart(name) {
            cart = cart.filter(item => item.name !== name);
            updateCart();
            localStorage.setItem('cart', JSON.stringify(cart));
        }

        function checkout() {
            const name = prompt("Enter your name:");
            const email = prompt("Enter your email:");
            if (name && email) {
                alert(`Order confirmed! Thank you, ${name}! Your order will be sent to ${email}.`);
                cart = [];
                updateCart();
                localStorage.setItem('cart', JSON.stringify(cart));
            }
        }

        document.getElementById('search').addEventListener('input', () => {
            const searchValue = document.getElementById('search').value.toLowerCase();
            products.forEach(product => {
                const productDiv = document.querySelector(`div.product h3:contains("${searchValue}")`);
                if (productDiv) {
                    productDiv.parentElement.style.display = 'block';
                } else {
                    productDiv.parentElement.style.display = 'none';
                }
            });
        });

        renderProducts();
    </script>
</body>
</html>
```

### Step 2: Save the HTML file

Create a file named `index.html` and paste the above code into it.

### Step 3: Start the preview

Run the following command to start the preview:

This will serve the `index.html` file and its assets from the current directory. The returned URL will be the preview URL for your local stationery storefront.

### Step 4: Access the preview URL

Open the returned URL in your web browser to see your local stationery storefront in action.

This approach ensures that everything is kept local and does not require any external dependencies. The cart persists across page reloads using `localStorage`.

